        "lang": "python",
        "code": "# A list keeps items in order; positions start at 0\nports = [22, 80, 443]\nports.append(8080)                 # add at the end\nprint(ports[0], ports[-1], len(ports))\n\n# A dictionary maps keys to values: one dict = one server\nserver = {\"host\": \"web-01\", \"env\": \"prod\", \"ports\": [22, 443]}\nserver[\"patched\"] = False          # add or change a key\nprint(server[\"host\"], server.get(\"owner\", \"unknown\"))\n\n# A list of dictionaries is the usual shape of an inventory (and of JSON data)\ninventory = [\n    {\"host\": \"web-01\", \"env\": \"prod\", \"ports\": [22, 443]},\n    {\"host\": \"db-01\", \"env\": \"prod\", \"ports\": [22, 5432]},\n    {\"host\": \"test-07\", \"env\": \"dev\", \"ports\": [22, 23, 8080]},\n]\n\nfor srv in inventory:\n    flag = \"TELNET!\" if 23 in srv[\"ports\"] else \"ok\"\n    print(f\"{srv['host']:8} {srv['env']:5} {len(srv['ports'])} ports  {flag}\")\n\n# List comprehension: build a new list from a filter, in one line\nprod_hosts = [srv[\"host\"] for srv in inventory if srv[\"env\"] == \"prod\"]\nprint(\"Production:\", prod_hosts)\n",
