        "lang": "python",
        "kind": "secure",
        "code": "import ipaddress\n\nBLOCKED = ipaddress.ip_network(\"203.0.113.0/24\")\n\n\ndef is_allowed(ip_text: str) -> bool:\n    \"\"\"Return True only for a valid IP address outside the blocked network.\"\"\"\n    try:\n        address = ipaddress.ip_address(ip_text)\n    except ValueError:\n        # Fail closed: an input we cannot parse is refused, never trusted\n        return False\n    return address not in BLOCKED\n\n\nfor candidate in [\"198.51.100.7\", \"203.0.113.50\", \"203.0.113.50 \", \"not-an-ip\"]:\n    print(f\"{candidate!r:16} allowed={is_allowed(candidate)}\")\n",
