        "code": "import io\n\n# Sample of /var/log/auth.log (OpenSSH server). The backslash avoids an empty first line.\nLOG = \"\"\"\\\nNov 12 03:14:07 web-01 sshd[2101]: Failed password for invalid user admin from 203.0.113.50 port 51234 ssh2\nNov 12 03:14:09 web-01 sshd[2101]: Failed password for root from 203.0.113.50 port 51236 ssh2\nNov 12 03:14:12 web-01 sshd[2103]: Failed password for root from 203.0.113.50 port 51240 ssh2\nNov 12 08:30:41 web-01 sshd[2188]: Accepted publickey for deploy from 198.51.100.7 port 40022 ssh2\nNov 12 09:02:10 web-01 sshd[2250]: Failed password for alice from 198.51.100.23 port 39900 ssh2\nNov 12 09:02:31 web-01 sshd[2250]: Accepted password for alice from 198.51.100.23 port 39900 ssh2\n\"\"\"\n\n# io.StringIO behaves like an opened text file. With a real file you would write:\n#   with open(\"/var/log/auth.log\", encoding=\"utf-8\", errors=\"replace\") as log_file:\nwith io.StringIO(LOG) as log_file:\n    total = 0\n    failed = 0\n    for line in log_file:                 # the file is read one line at a time\n        line = line.strip()               # remove the trailing newline\n        if not line:\n            continue\n        total += 1\n        if \"Failed password\" in line:\n            failed += 1\n            words = line.split()          # cut the line on whitespace\n            ip = words[words.index(\"from\") + 1]\n            print(f\"{words[2]} FAILED from {ip}\")\n\nprint(f\"{failed} failed logins out of {total} lines\")\n",
