        "code": "import socket\n\n\ndef is_open(host: str, port: int, timeout: float = 1.0) -> bool:\n    \"\"\"Return True if a TCP connection to host:port succeeds.\"\"\"\n    # AF_INET = IPv4, SOCK_STREAM = TCP. \"with\" closes the socket in every case.\n    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:\n        sock.settimeout(timeout)        # never wait forever on a filtered port\n        # connect_ex() returns 0 on success instead of raising an exception\n        return sock.connect_ex((host, port)) == 0\n\n\n# scanme.nmap.org is provided by the Nmap project to test scanners (be gentle)\nfor port in (22, 80, 443):\n    state = \"open\" if is_open(\"scanme.nmap.org\", port) else \"closed or filtered\"\n    print(f\"scanme.nmap.org:{port:<4} {state}\")\n",
