        "lang": "python",
        "code": "import socket\n\n\ndef grab_banner(host: str, port: int, timeout: float = 2.0) -> str:\n    \"\"\"Return the first line a service sends right after the connection.\"\"\"\n    try:\n        # create_connection() resolves the name, connects and applies the timeout\n        with socket.create_connection((host, port), timeout=timeout) as sock:\n            data = sock.recv(128)               # read at most 128 bytes\n    except OSError as error:                    # refused, timeout, DNS failure...\n        return f\"no banner ({error})\"\n    # Network data is untrusted bytes: decode defensively, keep the first line only\n    lines = data.decode(\"utf-8\", errors=\"replace\").splitlines()\n    return lines[0] if lines else \"no banner (empty answer)\"\n\n\nprint(\"22/tcp:\", grab_banner(\"scanme.nmap.org\", 22))\n",
