        "code": "#!/usr/bin/env python3\n\"\"\"portscan.py - concurrent TCP connect scanner with a scope guard.\n\nOnly scan systems you own or are explicitly authorised to test.\n\"\"\"\nimport argparse\nimport ipaddress\nimport json\nimport socket\nimport sys\nfrom concurrent.futures import ThreadPoolExecutor, as_completed\n\n# Networks this tool may touch. Add YOUR authorised ranges here, nothing else.\nAUTHORISED_SCOPE = [\n    ipaddress.ip_network(\"127.0.0.0/8\"),       # your own machine\n    ipaddress.ip_network(\"45.33.32.156/32\"),   # scanme.nmap.org, Nmap's public test host\n]\nMAX_WORKERS = 500\n\n\ndef parse_ports(spec: str) -> list[int]:\n    \"\"\"Turn \"22,80,8000-8010\" into a sorted list of valid port numbers.\"\"\"\n    ports: set[int] = set()\n    for part in spec.split(\",\"):\n        start, _, end = part.partition(\"-\")\n        first = int(start)                       # ValueError if not a number\n        last = int(end) if end else first\n        if not 1 <= first <= last <= 65535:\n            raise ValueError(f\"invalid port range: {part!r}\")\n        ports.update(range(first, last + 1))\n    return sorted(ports)\n\n\ndef resolve_in_scope(target: str) -> str:\n    \"\"\"Resolve the target once and refuse anything outside the authorised scope.\"\"\"\n    address = socket.gethostbyname(target)       # socket.gaierror if the name is unknown\n    ip = ipaddress.ip_address(address)\n    if not any(ip in network for network in AUTHORISED_SCOPE):\n        raise PermissionError(f\"{target} ({address}) is outside the authorised scope\")\n    # The caller scans this address, not the name: the name cannot be re-pointed mid-scan\n    return address\n\n\ndef check_port(address: str, port: int, timeout: float) -> tuple[int, bool]:\n    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:\n        sock.settimeout(timeout)\n        return port, sock.connect_ex((address, port)) == 0\n\n\ndef scan(address: str, ports: list[int], timeout: float, workers: int) -> list[int]:\n    open_ports = []\n    # The pool caps the number of simultaneous connections\n    with ThreadPoolExecutor(max_workers=workers) as pool:\n        futures = [pool.submit(check_port, address, port, timeout) for port in ports]\n        for future in as_completed(futures):\n            port, is_open = future.result()      # re-raises any error from the thread\n            if is_open:\n                open_ports.append(port)\n    return sorted(open_ports)\n\n\ndef main() -> int:\n    parser = argparse.ArgumentParser(description=\"TCP connect scanner (authorised targets only)\")\n    parser.add_argument(\"target\", help=\"host name or IPv4 address\")\n    parser.add_argument(\"-p\", \"--ports\", default=\"1-1024\", help='e.g. \"22,80,8000-8010\"')\n    parser.add_argument(\"-t\", \"--timeout\", type=float, default=1.0, help=\"seconds per port\")\n    parser.add_argument(\"-w\", \"--workers\", type=int, default=100, help=\"simultaneous connections\")\n    parser.add_argument(\"--allowed\", default=\"\", help=\"ports expected to be open; any other one fails the run\")\n    parser.add_argument(\"--json\", action=\"store_true\", help=\"machine-readable output\")\n    args = parser.parse_args()\n\n    try:\n        ports = parse_ports(args.ports)\n        allowed = set(parse_ports(args.allowed)) if args.allowed else None\n        address = resolve_in_scope(args.target)\n    except (ValueError, PermissionError, socket.gaierror) as error:\n        print(f\"error: {error}\", file=sys.stderr)\n        return 2\n\n    workers = max(1, min(args.workers, MAX_WORKERS))\n    open_ports = scan(address, ports, args.timeout, workers)\n    unexpected = sorted(set(open_ports) - allowed) if allowed is not None else []\n\n    if args.json:\n        print(json.dumps({\n            \"target\": args.target,\n            \"address\": address,\n            \"scanned\": len(ports),\n            \"open\": open_ports,\n            \"unexpected\": unexpected,\n        }))\n    else:\n        print(f\"Scanned {len(ports)} port(s) on {args.target} ({address})\")\n        for port in open_ports:\n            flag = \"  <-- NOT in the allow-list\" if port in unexpected else \"\"\n            print(f\"  {port}/tcp open{flag}\")\n        print(f\"{len(open_ports)} open, {len(unexpected)} unexpected\")\n\n    # Exit code 1 makes a CI job fail when an unexpected port is exposed\n    return 1 if unexpected else 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n",
        "output": "$ python3 -m http.server 8000 --bind 127.0.0.1 &\n$ python3 portscan.py 127.0.0.1 -p 7990-8010\nScanned 21 port(s) on 127.0.0.1 (127.0.0.1)\n  8000/tcp open\n1 open, 0 unexpected\n\n$ python3 portscan.py 127.0.0.1 -p 7990-8010 --allowed 22,443 --json\n{\"target\": \"127.0.0.1\", \"address\": \"127.0.0.1\", \"scanned\": 21, \"open\": [8000], \"unexpected\": [8000]}\n$ echo $?\n1\n\n$ python3 portscan.py 192.0.2.10 -p 80\nerror: 192.0.2.10 (192.0.2.10) is outside the authorised scope\n",
