        "lang": "python",
        "code": "import socket\nfrom concurrent.futures import ThreadPoolExecutor\n\nTARGET = \"127.0.0.1\"          # your own machine only\nTIMEOUT = 0.5\nPORTS = list(range(1, 1025)) + [8000]\n\n\ndef is_open(port: int) -> bool:\n    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:\n        sock.settimeout(TIMEOUT)\n        return sock.connect_ex((TARGET, port)) == 0\n\n\ndef service_name(port: int) -> str:\n    try:\n        return socket.getservbyport(port, \"tcp\")\n    except OSError:           # no entry for this port in the services database\n        return \"unknown\"\n\n\nwith ThreadPoolExecutor(max_workers=100) as pool:\n    # map() calls is_open(port) for every port and yields results in the SAME order\n    results = list(pool.map(is_open, PORTS))\n\nopen_ports = [port for port, opened in zip(PORTS, results) if opened]\nfor port in open_ports:\n    print(f\"{port:>5}/tcp  {service_name(port)}\")\nprint(f\"{len(open_ports)} open port(s) on {TARGET}\")\n",
