        "code": "import ipaddress\nimport subprocess\n\n\ndef ping(host: str) -> bool:\n    \"\"\"Return True if the host answers one ICMP echo request.\"\"\"\n    # 1. Allow-list validation: only a real IP address goes further.\n    #    This also blocks option injection (a value starting with \"-\").\n    address = ipaddress.ip_address(host)      # raises ValueError otherwise\n\n    # 2. A list, no shell: each item is passed to ping as ONE argument\n    result = subprocess.run(\n        [\"ping\", \"-c\", \"1\", \"-W\", \"2\", str(address)],\n        capture_output=True,\n        text=True,\n        timeout=5,        # 3. never hang forever\n        check=False,      # exit code 1 just means \"no answer\", it is not an error\n    )\n    return result.returncode == 0\n\n\nfor candidate in [\"127.0.0.1\", \"127.0.0.1; id\", \"-f\"]:\n    try:\n        print(f\"{candidate!r}: {'up' if ping(candidate) else 'down'}\")\n    except ValueError as error:\n        print(f\"{candidate!r}: rejected ({error})\")\n",
