        "code": "import json\nimport re\nimport subprocess\nimport sys\n\n# Allow-list for an image reference: must start with a letter or digit (never \"-\")\nIMAGE_REF = re.compile(r\"[a-z0-9][a-z0-9._/:@-]{0,254}\")\n\n\ndef scan_image(image: str) -> list[dict]:\n    \"\"\"Run Trivy on a container image and return its HIGH/CRITICAL vulnerabilities.\"\"\"\n    if IMAGE_REF.fullmatch(image) is None:\n        raise ValueError(f\"invalid image reference: {image!r}\")\n\n    command = [\"trivy\", \"image\", \"--quiet\", \"--format\", \"json\",\n               \"--severity\", \"HIGH,CRITICAL\", image]\n    try:\n        completed = subprocess.run(command, capture_output=True, text=True,\n                                   timeout=600, check=True)\n    except FileNotFoundError:\n        sys.exit(\"error: trivy is not installed or not in PATH\")\n    except subprocess.TimeoutExpired:\n        sys.exit(\"error: trivy did not finish within 10 minutes\")\n    except subprocess.CalledProcessError as error:\n        # stderr explains the failure (unknown image, registry unreachable...)\n        sys.exit(f\"error: trivy exited with code {error.returncode}: {error.stderr.strip()}\")\n\n    report = json.loads(completed.stdout)\n    findings = []\n    for result in report.get(\"Results\", []):\n        findings.extend(result.get(\"Vulnerabilities\", []))\n    return findings\n\n\nif __name__ == \"__main__\":\n    image = sys.argv[1] if len(sys.argv) > 1 else \"python:3.9-slim\"\n    vulnerabilities = scan_image(image)\n    for vuln in vulnerabilities:\n        print(f\"{vuln['Severity']:8} {vuln['VulnerabilityID']:16} {vuln['PkgName']}\")\n    print(f\"{len(vulnerabilities)} HIGH/CRITICAL vulnerabilities in {image}\")\n    sys.exit(1 if vulnerabilities else 0)      # non-zero exit code fails the CI job\n",
