        "file": "alerts_to_slack.py",
        "lang": "python",
        "kind": "secure",
        "code": "#!/usr/bin/env python3\n\"\"\"Post the open high/critical Dependabot alerts of a repository to Slack.\n\nEnvironment variables (injected by the CI or a secrets manager):\n  GITHUB_TOKEN       token with read access to Dependabot alerts\n  SLACK_WEBHOOK_URL  Slack incoming webhook (the URL itself is a secret)\nUsage: python3 alerts_to_slack.py example-org/shop-api\n\"\"\"\nimport os\nimport re\nimport sys\n\nimport requests\nfrom requests.adapters import HTTPAdapter\nfrom urllib3.util.retry import Retry\n\nGITHUB_API = \"https://api.github.com\"\nTIMEOUT = (3.05, 15)        # (connect, read) in seconds, on EVERY request\nREPO = re.compile(r\"[A-Za-z0-9_.-]{1,100}/[A-Za-z0-9_.-]{1,100}\")\n\n\ndef github_session(token: str) -> requests.Session:\n    session = requests.Session()\n    session.headers.update({\n        \"Authorization\": f\"Bearer {token}\",\n        \"Accept\": \"application/vnd.github+json\",\n        \"X-GitHub-Api-Version\": \"2022-11-28\",\n    })\n    # Retry temporary failures with exponential backoff; 401/403/404 are NOT retried\n    retry = Retry(total=3, backoff_factor=1,\n                  status_forcelist=(429, 500, 502, 503, 504),\n                  allowed_methods=(\"GET\",))\n    session.mount(\"https://\", HTTPAdapter(max_retries=retry))\n    return session\n\n\ndef open_alerts(session: requests.Session, repo: str) -> list[dict]:\n    response = session.get(\n        f\"{GITHUB_API}/repos/{repo}/dependabot/alerts\",\n        params={\"state\": \"open\", \"severity\": \"critical,high\", \"per_page\": 100},\n        timeout=TIMEOUT,\n    )\n    response.raise_for_status()      # 4xx/5xx become an exception\n    return response.json()\n\n\ndef notify_slack(webhook_url: str, text: str) -> None:\n    # Plain requests.post, NOT the GitHub session: the GitHub token must never\n    # be sent to another host\n    response = requests.post(webhook_url, json={\"text\": text}, timeout=TIMEOUT)\n    response.raise_for_status()\n\n\ndef main() -> int:\n    if len(sys.argv) != 2 or REPO.fullmatch(sys.argv[1]) is None:\n        print(\"usage: alerts_to_slack.py OWNER/REPO\", file=sys.stderr)\n        return 2\n    repo = sys.argv[1]\n\n    try:\n        token = os.environ[\"GITHUB_TOKEN\"]\n        webhook_url = os.environ[\"SLACK_WEBHOOK_URL\"]\n    except KeyError as missing:\n        print(f\"error: environment variable {missing} is not set\", file=sys.stderr)\n        return 2\n\n    try:\n        alerts = open_alerts(github_session(token), repo)\n        if alerts:\n            lines = [f\":rotating_light: {len(alerts)} open high/critical alert(s) in {repo}\"]\n            for alert in alerts:\n                advisory = alert[\"security_advisory\"]\n                package = alert[\"dependency\"][\"package\"][\"name\"]\n                lines.append(f\"- [{advisory['severity']}] {package}: {advisory['summary']}\")\n            notify_slack(webhook_url, \"\\n\".join(lines))\n    except requests.RequestException as error:\n        # Log the kind of failure and the status code, never the token or the webhook URL\n        status = getattr(error.response, \"status_code\", \"no response\")\n        print(f\"error: API call failed ({type(error).__name__}, status: {status})\", file=sys.stderr)\n        return 2\n\n    print(f\"{len(alerts)} open high/critical alert(s) in {repo}\")\n    return 1 if alerts else 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n",
        "output": "$ export GITHUB_TOKEN=\"$(gh auth token)\"\n$ export SLACK_WEBHOOK_URL=\"$(vault kv get -field=url secret/ci/slack)\"\n$ python3 alerts_to_slack.py example-org/shop-api\n2 open high/critical alert(s) in example-org/shop-api\n$ echo $?\n1\n",
