        "code": "import sys\n\nimport requests\n\nOSV_QUERY_URL = \"https://api.osv.dev/v1/query\"\nTIMEOUT = (3.05, 15)\nDEPENDENCIES = {\"flask\": \"2.2.2\", \"requests\": \"2.32.3\", \"jinja2\": \"2.11.2\"}\n\n\ndef known_vulnerabilities(session: requests.Session, name: str, version: str) -> list[dict]:\n    payload = {\"version\": version, \"package\": {\"name\": name, \"ecosystem\": \"PyPI\"}}\n    response = session.post(OSV_QUERY_URL, json=payload, timeout=TIMEOUT)\n    response.raise_for_status()\n    # OSV answers {} when nothing is known: default to an empty list\n    return response.json().get(\"vulns\", [])\n\n\ndef main() -> int:\n    vulnerable = 0\n    # One session = one TLS connection reused for all the requests\n    with requests.Session() as session:\n        for name, version in DEPENDENCIES.items():\n            try:\n                vulns = known_vulnerabilities(session, name, version)\n            except requests.RequestException as error:\n                print(f\"error: OSV query failed for {name}: {type(error).__name__}\", file=sys.stderr)\n                return 2\n            if not vulns:\n                print(f\"ok          {name}=={version}\")\n                continue\n            vulnerable += 1\n            print(f\"VULNERABLE  {name}=={version}\")\n            for vuln in vulns:\n                print(f\"    {vuln['id']}: {vuln.get('summary', 'no summary')}\")\n    return 1 if vulnerable else 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n",
